using namespace fluxus;
namespace fs = std::filesystem;

void check(bool condition,const std::string& message){if(!condition)throw std::runtime_error(message);}
void writeLines(const fs::path&path,const std::vector<std::string>&lines){std::ofstream out(path,std::ios::binary);for(const auto&line:lines)out<<line<<'\n';}
std::string readGzip(const fs::path&path){gzFile file=gzopen(path.c_str(),"rb");check(file!=nullptr,"gzip open");std::string result;char buffer[8192];int count;while((count=gzread(file,buffer,sizeof(buffer)))>0)result.append(buffer,count);gzclose(file);return result;}
void writeGzip(const fs::path&path,const std::string&text){gzFile file=gzopen(path.c_str(),"wb");check(file!=nullptr,"gzip create");check(gzwrite(file,text.data(),static_cast<unsigned>(text.size()))==static_cast<int>(text.size()),"gzip write");gzclose(file);}

void limaTest(){LimaAnalyzer a;a.processLine("15/10 14:11:00 DBG type: DEVICE_EVENT_TYPE_BILL_ACCEPTOR_BANKNOTE_INSERTED banknote: { banknote: 1000 } currency: \"USD\" banknote_uuid: \"abc\" banknote_id: 7 model: \"NV9\" serial_number: \"S1\" vendor: \"ITL\" timestamp_ms: 1000");a.processLine("15/10 14:11:01 DBG type: DEVICE_EVENT_TYPE_BILL_ACCEPTOR_BANKNOTE_STACKING banknote: 1000 currency: \"USD\" banknote_uuid: \"abc\" model: \"NV9\" serial_number: \"S1\" timestamp_ms: 2000");a.processLine("15/10 14:11:02 DBG BanknoteValidator event=\"Safe Note Jam\" timestamp_ms: 2500");a.processLine("15/10 14:11:03 DBG type: DEVICE_EVENT_TYPE_BILL_ACCEPTOR_BANKNOTE_STACKED banknote: 1000 currency: \"USD\" banknote_uuid: \"abc\" model: \"NV9\" serial_number: \"S1\" timestamp_ms: 3000");a.processLine("15/10 14:12:00 DBG COLLECTION REPORT Print notes=\"$5 x 2, $10 x 1\"");a.buildSessions();check(a.sessions.size()==1,"Lima sessions");check(a.sessions[0].status=="STACKED","Lima status");check(a.sessions[0].events.size()==4,"Lima BNV correlation");check(a.totalCount==1&&a.totalSum==10,"Lima totals");check(a.stats["USD"][10]==1,"Lima stats");check(a.collections[0].notes[5]==2,"Lima collection");check(a.bnvEventsCount["Safe Note Jam"]==1,"Lima BNV count");}

void frontendTest(){const std::string trx="123e4567-e89b-42d3-a456-426614174000";W2FrontendAnalyzer a;
a.processLine("[10/11/2026, 4:28:20 PM] payoutCoupon {\"trx\":\""+trx+"\",\"coupon\":{\"low\":-10000},\"groupUuid\":\"group1\",\"payoutCoupon\":{\"status\":\"ok\"},\"amount\":{\"low\":10000}}");
a.processLine("[10/11/2026, 4:28:21 PM] payoutCouponAPI trx "+trx+" login: 42");
a.processLine("[10/11/2026, 4:28:22 PM] INSERT INTO terminal_balances `trx` = '"+trx+"', `sum` = 10000, `user_login` = '42'");
a.processLine("[10/11/2026, 4:28:23 PM] DispenserService.dispense login: '42' commands [{\"deviceId\":\"D1\",\"bankIndex\":1,\"notesAmount\":2}] nominal and current count [[1,100],[5,50]]");
a.processLine("[10/11/2026, 4:28:24 PM] processNewEvent login: '42' {\"type\":16,\"dispensed\":{\"bankIndex\":1,\"notesAmountRequested\":2,\"notesAmountDispensed\":2},\"model\":\"LCDM4000\",\"device\":{\"id\":\"D1\"},\"vendor\":\"ITL\"}");
a.processLine("[10/11/2026, 4:28:25 PM] INSERT INTO terminal_transactions_box login: '42' VALUES (7, 1, 50, 2, 2)");
a.processLine("[10/11/2026, 4:28:26 PM] UPDATE terminal_transactions `sum` = 10000, `status` = 'ok' where id = 7 login: '42'");
a.processLine("[10/11/2026, 4:28:27 PM] rawTemplate Cash in addedToDispenserBoxes:\"Box 1\\n$5*10 = $50\" totalSum:\"50\"");a.buildSessions();
check(a.sessions.size()==1,"W2 sessions");const auto&s=*a.sessions[0];check(s.status=="OK","W2 status");check(s.requestedAmount==10000&&s.dispensedAmount==10000,"W2 amounts");check(s.dispenserDeviceId=="D1"&&s.dispenserModel=="LCDM4000","W2 device");check(eventInt(s.boxes[0],"count")==2,"W2 boxes");check(a.cashEvents.size()==1,"W2 cash");check(a.cashEvents[0].boxesDelta.at(1)==10&&a.cashEvents[0].totalCents==5000,"W2 cash values");}

void lowLevelTest(){W2LowLevelAnalyzer a;for(const std::string&line:std::vector<std::string>{
"15/10 14:11:00 DBG Handle Dispense Request: reqID=1 commands=1 serialPath=/dev/ttyUSB0","15/10 14:11:00 DBG Handle Dispense Request: reqID=1 cmdIndex=0 bankIndex=1 amount=1 serialPath=/dev/ttyUSB0","15/10 14:11:01 DBG Dispense worker: job start reqID=1 jobID=9 serialPath=/dev/ttyUSB0","15/10 14:11:01 DBG Dispense: start reqID=1 jobID=9 cmdIndex=0 bankIndex=1 amount=1 serialPath=/dev/ttyUSB0","15/10 14:11:02 DBG Dispense: status=0x30 (Good) serialPath=/dev/ttyUSB0","15/10 14:11:03 DBG CommandDispense: chk=1 disp=1 rej=0 serialPath=/dev/ttyUSB0","15/10 14:11:04 DBG Dispense: event OK reqID=1 jobID=9 cmdIndex=0 bankIndex=1 amount=1 requested=1 chk=1 dispensed=1 rejected=0 serialPath=/dev/ttyUSB0","15/10 14:12:00 DBG LCDM4000 CCTalk: Dispense sequence: start command bankIndex=2 notesAmount=2 serialPath=/dev/ttyUSB1","15/10 14:12:01 DBG LCDM4000 CCTalk: Dispense: note result bankIndex=2 chkSensorTotal=2 deviceCode=0 deviceDescription=\"No error\" dispensedTotal=2 noteDispensed=1 noteN=2 noteRejected=0 serialPath=/dev/ttyUSB1","15/10 14:12:02 DBG LCDM4000 CCTalk: Dispense: finished bankIndex=2 chkSensorTotal=2 dispensedTotal=2 notesAmount=2 rejectedTotal=0 serialPath=/dev/ttyUSB1","15/10 14:12:03 DBG LCDM4000 CCTalk: Command: Status SensorDVTL=ok SensorDVTR=ok SensorEJT=ok SensorEXIT=ok SensorRJT=ok","15/10 14:12:04 DBG LCDM4000 CCTalk: Command: Status Cassette1Exists=true Cassette1Length=10 Cassette1Opacity=20 Cassette1Status=0"})a.processLine(line);a.buildSessions();check(a.sessions.size()==2,"LL sessions");for(const auto&s:a.sessions)check(s->status=="OK","LL status");check(a.sessions[0]->totalDispensed()==1&&a.sessions[1]->totalDispensed()==2,"LL totals");check(a.lcdmHealth.size()==2&&a.lcdmHealthChanges.size()==2,"LL health");}

void correlationTest(){auto front=std::make_shared<W2WithdrawSession>("trx");front->commands.push_back({{"bankIndex",1},{"notesAmount",1}});front->addEvent({{"kind","dispenseCommand"},{"dt",DateTime{2026,10,11,12,0,0}.iso()}});auto low=std::make_shared<W2LowLevelSession>();low->model="LCDM2000";low->commands.push_back({{"bankIndex",1},{"amount",1}});low->addEvent("cmdStart",{2026,10,11,12,1,0},"start");low->results.push_back({{"dispensed",1},{"rejected",0}});W2LowLevelAnalyzer a;a.sessions.push_back(low);a.correlateWithFrontend({front});check(front->lowLevelSessions.size()==1&&front->lowLevelSessions[0]==low,"correlation link");check(front->allSuspicionFlags().at(0)=="gap +60s","correlation gap");}

void engineTest(const fs::path&dir){const auto path=dir/"devices_server.log";writeLines(path,{"15/10 14:11:00 DBG type: DEVICE_EVENT_TYPE_BILL_ACCEPTOR_BANKNOTE_STACKED banknote: 500 currency: \"USD\" model: \"NV9\" serial_number: \"S1\" timestamp_ms: 1","15/10 14:11:01 DBG Handle Dispense Request: reqID=2 commands=1 serialPath=/dev/ttyUSB0","15/10 14:11:02 DBG Handle Dispense Request: reqID=2 cmdIndex=0 bankIndex=1 amount=1 serialPath=/dev/ttyUSB0"});auto result=AnalysisEngine::analyzeDevice({path.string()});check(result.lima.totalCount==1&&result.lima.sessions.size()==1,"engine Lima");check(result.w2LowLevel.sessions.size()==1,"engine low");check(result.w2LowLevel.linesProcessed==static_cast<std::int64_t>(result.lima.allEvents.size()+2),"engine one pass");}

AnalysisResult sample(){AnalysisResult r;r.sourceFiles={"devices_server.log"};BanknoteSession bank(0,{{"timestamp",1000},{"date","11/10/2026"},{"time","12:00:00"},{"event_type","DEVICE_EVENT_TYPE_BILL_ACCEPTOR_BANKNOTE_STACKED"},{"banknote_uuid","abc"},{"banknote_raw",1000},{"currency","USD"},{"device_model","NV9"},{"device_serial","S1"}});r.lima.sessions.push_back(bank);r.lima.totalCount=1;r.lima.totalSum=10;r.lima.stats["USD"][10]=1;auto low=std::make_shared<W2LowLevelSession>();low->model="LCDM2000";low->status="OK";low->addEvent("cmdStart",{2026,10,11,12,1,0},"start");r.w2LowLevel.sessions.push_back(low);auto front=std::make_shared<W2WithdrawSession>("trx");front->status="OK";front->requestedAmount=front->dispensedAmount=100;front->addEvent({{"kind","dispenseCommand"},{"dt",DateTime{2026,10,11,12,0,0}.iso()}});front->lowLevelSessions.push_back(low);front->suspicionFlags={{"gap +60s"}};r.w2Frontend.sessions.push_back(front);r.w2Frontend.restoreSessions(r.w2Frontend.sessions);W2CashEvent cash(W2CashEvent::CashIn,DateTime{2026,10,11,13,0,0});cash.boxesDelta[1]=10;cash.totalCents=5000;cash.rawDetails="Box 1";r.w2Frontend.cashEvents.push_back(cash);return r;}

void serializationTest(const fs::path&dir){const auto path=dir/"result.anl.gz";AnalysisSerializer::save(path,sample());auto r=AnalysisSerializer::load(path);check(r.version==2&&r.lima.sessions.size()==1,"serializer v2");check(r.w2Frontend.sessions.size()==1&&r.w2LowLevel.sessions.size()==1,"serializer sessions");const auto&s=r.w2Frontend.sessions[0];check(s->lowLevelSessions.size()==1&&s->lowLevelSessions[0]==r.w2LowLevel.sessions[0],"serializer links");check(s->startDateTime&&*s->startDateTime==DateTime{2026,10,11,12,0,0},"serializer date");check(s->suspicionFlags.at(0).at(0)=="gap +60s","serializer flags");check(r.w2Frontend.cashEvents[0].boxesDelta.at(1)==10&&r.w2Frontend.cashEvents[0].totalCents==5000,"serializer cash");check(r.lima.stats["USD"][10]==1,"serializer stats");}

void legacyTest(const fs::path&dir){const auto path=dir/"legacy.anl.gz";AnalysisSerializer::save(path,sample());auto root=Json::parse(readGzip(path));root["version"]=1;root["w2_frontend"].erase("cash_events");for(auto&s:root["w2_frontend"]["sessions"]){s.erase("cassette_mismatch");s.erase("cassette_mismatch_details");}writeGzip(path,root.dump());auto r=AnalysisSerializer::load(path);check(r.version==1&&r.w2Frontend.cashEvents.empty(),"legacy cash");check(!r.w2Frontend.sessions[0]->cassetteMismatch&&r.w2Frontend.sessions[0]->cassetteMismatchGroupSize==1,"legacy defaults");}

void gzipTest(const fs::path&dir){const auto path=dir/"skills-battle-frontend.log.gz";writeGzip(path,"[10/11/2026, 4:28:25 PM] payoutCoupon\n");check(detectLogType(path)=="frontend","gzip detect");LineReader reader(path);std::string line;check(reader.readLine(line)&&line.find("payoutCoupon")!=std::string::npos,"gzip read");check(safeFilename("device / 001")=="device_001","safe name");}

void configTest(const fs::path&dir){const fs::path configDir=dir/"config";fs::create_directories(configDir);writeLines(configDir/"config.json",{"{\"ssh_key_path\":\"id_rsa\",\"default_device_password\":\"pw\",\"theme\":\"dark\",\"devices\":[{\"id\":\"001\",\"host\":\"10.8.0.1\",\"comment\":\"Office\"}],\"last_window_geometry\":[1,2,800,600],\"auto_check_updates\":false}"});auto&config=Config::instance();config.setDataDirectory(configDir);check(config.string("ssh_key_path")=="id_rsa"&&config.string("default_device_password")=="pw","config values");check(config.devices().size()==1&&config.devices()[0].host=="10.8.0.1","config devices");check(!config.boolean("auto_check_updates"),"config bool");config.set("test_key","value",true);check(config.get("test_key")=="value","config save");}

int main(){int passed=0;const auto dir=fs::temp_directory_path()/("fluxus-cpp-tests-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(dir);auto run=[&](const std::string&name,auto test){test();++passed;std::cout<<"[PASS] "<<name<<'\n';};
try{run("Lima lifecycle",limaTest);run("W2 frontend",frontendTest);run("LCDM2000/4000",lowLevelTest);run("Correlation",correlationTest);run("One-pass engine",[&]{engineTest(dir);});run("Serialization v2",[&]{serializationTest(dir);});run("Legacy v1",[&]{legacyTest(dir);});run("Gzip utilities",[&]{gzipTest(dir);});run("Config compatibility",[&]{configTest(dir);});std::cout<<"All "<<passed<<" tests passed\n";fs::remove_all(dir);return 0;}catch(const std::exception&e){std::cerr<<"[FAIL] "<<e.what()<<'\n';fs::remove_all(dir);return 1;}}
